function canUseAssistant() { return state.authenticated && state.pluginEnabled && state.role !== 'disabled'; }
function isModal() { return state.open && (state.expanded || state.width < ASSISTANT_FIXTURE.layout.wide_breakpoint); }
function resolveAssets(value) {
  return value.split('../../../app/static/cir-application-logo.svg').join(ASSETS.logo)
    .split('../../visual-assets/cybersecurity-hero-v2.png').join(ASSETS.hero);
}
function scriptText(value) { return value.replace(/<\/script/gi, '<\\/script'); }
