function setPage(page) {
  if(!PAGE_SOURCES[page])return false;
  if(state.page!==page){state.page=page;clearConversation(state.tenant==='default');loadPage();renderContext();}
  return true;
}
function submitQuestion(question) {
  if(!canUseAssistant()||!state.open)return false;
  const text=String(question||'').trim();if(!text)return false;
  const suggestion=ASSISTANT_FIXTURE.suggestions.find(item=>item.question.toLowerCase()===text.toLowerCase());
  const answer=suggestion?(ASSISTANT_FIXTURE.conversations[suggestion.answer_key]||ASSISTANT_FIXTURE.extra_answers[suggestion.answer_key]):{
    intro:'Questa anteprima contiene risposte dimostrative sulle funzioni di CIR.',
    steps:[],outro:'Puoi scegliere una delle domande suggerite per esplorare l’impaginazione della chat.'};
  state.messages.push({type:'user',text},{type:'bot',answer});
  $('assistant-question').value='';state.selectedAnswer=null;renderConversation();
  const scroll=$('assistant-scroll');scroll.scrollTop=scroll.scrollHeight;
  $('assistant-announcement').textContent='Risposta dimostrativa disponibile.';
  return true;
}
function setPlugin(enabled) {
  state.pluginEnabled=Boolean(enabled);
  if(!state.pluginEnabled){clearConversation();state.open=false;state.expanded=false;}
  const api=frameApi();if(api?.setCapabilities)api.setCapabilities({chatbot_enabled:state.pluginEnabled});
  applyLayout();return true;
}
function setAuthenticated(authenticated) {
  state.authenticated=Boolean(authenticated);
  clearConversation();if(!state.authenticated){state.open=false;state.expanded=false;}
  applyLayout();return true;
}
function setRole(role) {
  if(!['superuser','admin','writer','reader','operator','disabled'].includes(role))return false;
  state.role=role;clearConversation();
  const api=frameApi();if(api?.setRole)api.setRole(role);
  const next=api?.state?.tenant||(role==='superuser'?state.tenant:'default');
  state.tenant=next;applyLayout();return true;
}
function setViewport(width) {
  const next=Number(width);if(!Number.isFinite(next)||next<240)return false;
  state.width=next;applyLayout();return true;
}
function focusableInPanel() {
  return [...$('assistant-panel').querySelectorAll('button:not([disabled]), textarea:not([disabled]), [tabindex="0"]')].filter(element=>!element.hidden && element.offsetParent!==null);
}
$('page-frame').addEventListener('load',installFrameBridge);
$('assistant-close').addEventListener('click',closeAssistant);
$('assistant-back').addEventListener('click',closeAssistant);
$('assistant-expand').addEventListener('click',()=>openAssistant(true));
$('assistant-backdrop').addEventListener('click',closeAssistant);
$('assistant-form').addEventListener('submit',event=>{event.preventDefault();submitQuestion($('assistant-question').value);});
$('clear-chat').addEventListener('click',()=>{if(!canUseAssistant())return;clearConversation();$('assistant-question').focus();});
$('context-toggle').addEventListener('click',()=>{const open=$('context-details').hidden;$('context-details').hidden=!open;$('context-toggle').setAttribute('aria-expanded',open?'true':'false');});
document.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>setPage(button.dataset.page)));
$('suggestions').addEventListener('click',event=>{const button=event.target.closest('[data-suggestion]');if(!button||!canUseAssistant())return;const item=ASSISTANT_FIXTURE.suggestions[Number(button.dataset.suggestion)];if(!item)return;$('assistant-question').value=item.question;$('assistant-question').focus();});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&state.open){event.preventDefault();closeAssistant();return;}
  if(event.key==='Tab'&&isModal()){
    const list=focusableInPanel();if(!list.length)return;
    if(event.shiftKey&&(document.activeElement===list[0]||document.activeElement===$('assistant-heading'))){event.preventDefault();list[list.length-1].focus();}
    else if(!event.shiftKey&&(document.activeElement===list[list.length-1]||document.activeElement===$('assistant-heading'))){event.preventDefault();list[0].focus();}
  }
});
window.addEventListener('resize',()=>setViewport(window.innerWidth));
// Review-only controls. They are not authentication, application permissions or AI tools.
window.CIRAssistantReview={state,fixture:ASSISTANT_FIXTURE,open:openAssistant,close:closeAssistant,setPage,setTenant:switchTenant,
  setPlugin,setAuthenticated,setRole,setViewport,submit:submitQuestion,reset:clearConversation,frameSource,installFrameBridge,
  status:()=>({page:state.page,tenant:state.tenant,open:state.open,mode:state.open?(isModal()?'focus':'dock'):'closed',
    available:canUseAssistant(),messages:state.messages.length,requestShape:{question:'only current question'},automaticIncidentContext:false,historySent:false})};
clearConversation(true);loadPage();
if(state.width>=ASSISTANT_FIXTURE.layout.wide_breakpoint)openAssistant();else applyLayout();
